*{box-sizing:border-box} :root{--ink:#f4f4e9;--muted:#a1afa8;--gold:#e5c785;--teal:#a9d8c6;--panel:rgba(15,27,29,.82);--line:rgba(233,239,222,.14)}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#142522;color:var(--ink);font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit;cursor:pointer;border:0} .game-shell{position:relative;width:100%;height:100%;min-height:500px;overflow:hidden;background:#203d33}#world{position:absolute;inset:0;width:100%;height:100%;display:block}.world-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(8,19,21,.58) 0%,transparent 19%,transparent 68%,rgba(9,18,19,.58) 100%),linear-gradient(90deg,rgba(7,18,20,.32),transparent 30%,transparent 72%,rgba(7,18,20,.25))}.glass{background:var(--panel);border:1px solid var(--line);box-shadow:0 12px 35px rgba(6,15,14,.2);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px)}.topbar{position:absolute;top:0;left:0;right:0;height:74px;padding:0 35px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.09);background:linear-gradient(180deg,rgba(10,21,23,.64),rgba(10,21,23,.1))}.brand{display:flex;align-items:center;gap:10px;color:var(--ink);text-decoration:none;font:800 13px Manrope,sans-serif;letter-spacing:2.1px}.brand-mark{font-size:30px;color:var(--gold);line-height:1}.brand small{display:block;color:#aab8ad;font:500 8px 'DM Mono',monospace;letter-spacing:2.7px;margin-top:3px}.region-pill{position:absolute;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:10px;color:#d2dccf;font:500 9px 'DM Mono',monospace;letter-spacing:1.6px}.live-dot{height:6px;width:6px;border-radius:50%;background:#c5d98a;box-shadow:0 0 12px #c5d98a}.region-pill i{font-style:normal;color:var(--gold)}.top-actions{display:flex;align-items:center;gap:10px}.icon-button,.avatar-button{width:34px;height:34px;border:1px solid rgba(231,233,218,.21);border-radius:50%;background:rgba(16,31,31,.6);color:#e8e8d9;font-size:17px}.avatar-button{background:#d7c38c;color:#293330;font-weight:800;font-size:13px;border:0}.player-card{position:absolute;top:94px;left:35px;width:278px;padding:14px;display:flex;align-items:center;gap:12px;border-radius:10px}.portrait{width:44px;height:44px;flex:none;border-radius:50%;display:grid;place-items:center;color:#e3d4a0;font-size:24px;background:radial-gradient(circle at 50% 35%,#a4bfa0 0,#537264 40%,#293c38 72%);border:1px solid rgba(220,215,173,.4);position:relative}.portrait-level{position:absolute;right:-3px;bottom:-2px;border-radius:8px;background:#d8c68b;color:#25332e;padding:2px 4px;font:700 8px 'DM Mono',monospace}.player-info{flex:1;min-width:0}.player-name{font:700 13px Manrope,sans-serif;margin-bottom:8px}.rank{color:#d8c68b;font:500 8px 'DM Mono',monospace;letter-spacing:1px;margin-left:6px}.stat-label{display:flex;justify-content:space-between;font:500 7px 'DM Mono',monospace;color:#bbc6b8;letter-spacing:.7px;margin-bottom:3px}.meter{height:4px;background:rgba(226,233,218,.15);border-radius:5px;overflow:hidden}.meter i{height:100%;width:100%;display:block;background:linear-gradient(90deg,#d79376,#efb587);border-radius:5px;transition:width .25s}.meter.xp i{background:linear-gradient(90deg,#92c6b1,#d6cf91);width:0}.xp-label{margin-top:7px}.tiny-settings{background:none;color:#b9c9b8;font-size:18px;padding:3px}.quest-card{position:absolute;left:35px;top:212px;width:278px;padding:14px 16px 13px;border-radius:9px}.quest-heading{display:flex;align-items:center;gap:7px;color:#d8c68b;font:500 8px 'DM Mono',monospace;letter-spacing:1.6px;margin-bottom:12px}.quest-symbol{font-size:13px}.quest-heading button{margin-left:auto;background:none;color:#a9b5a6;font-size:16px}.quest-card strong{font:700 14px Manrope,sans-serif}.quest-card p{color:#bac5b8;font-size:10px;line-height:1.55;margin:5px 0 12px}.quest-progress{display:flex;align-items:center;gap:8px;color:#d4d7c1;font:9px 'DM Mono',monospace}.mini-meter{height:4px;background:rgba(228,230,212,.13);flex:1;border-radius:9px;overflow:hidden}.mini-meter i{display:block;width:0;height:100%;background:#b4cf9a;transition:width .3s}.quest-reward{margin-top:11px;padding-top:9px;border-top:1px solid rgba(255,255,255,.08);font:8px 'DM Mono',monospace;letter-spacing:.5px;color:#d8c68b;display:flex;gap:7px}.location-label{position:absolute;left:50%;top:111px;transform:translateX(-50%);text-align:center;display:flex;flex-direction:column;gap:4px;text-shadow:0 2px 9px #10231e}.location-kicker{font:500 8px 'DM Mono',monospace;letter-spacing:2.4px;color:#e2d5a9}.location-label strong{font:600 19px Manrope,sans-serif;letter-spacing:.2px}.location-sub{font-size:10px;color:#d5decf}.right-rail{position:absolute;right:35px;top:94px;width:228px;display:flex;flex-direction:column;gap:11px}.resource-card{display:flex;align-items:center;padding:11px 12px;gap:10px;border-radius:9px}.resource-icon{color:#dec68d;font-size:21px}.resource-card small{font:8px 'DM Mono',monospace;letter-spacing:1px;color:#aeb9a9;display:block}.resource-card strong{font:700 14px Manrope,sans-serif}.resource-card button{margin-left:auto;background:rgba(235,230,201,.09);border:1px solid rgba(235,230,201,.15);border-radius:50%;width:24px;height:24px;color:#d8c68b}.circle-card,.nearby-card{padding:13px;border-radius:9px}.section-title{font:500 8px 'DM Mono',monospace;letter-spacing:1.5px;color:#c5cabb;margin-bottom:10px}.section-title>span{float:right;color:#d8c68b}.creature-row{display:flex;align-items:center;gap:9px;padding:8px 0;border-top:1px solid rgba(255,255,255,.07)}.creature-icon{width:34px;height:34px;display:grid;place-items:center;border-radius:50%;font-size:18px;position:relative}.creature-icon ember{color:#f0bb83}.creature-icon.water{color:#9ed4da}.creature-icon.leaf{color:#bdd598}.creature-detail{min-width:0;flex:1}.creature-detail strong{font:600 10px Manrope,sans-serif;display:block}.creature-detail small{font:8px 'DM Mono',monospace;color:#aab8ac}.creature-hp{font:8px 'DM Mono',monospace;color:#b1c6a9}.creature-health{height:3px;background:rgba(240,240,220,.1);margin-top:4px;border-radius:4px}.creature-health i{display:block;height:100%;background:#9cc8a2;border-radius:4px}.manage-link{display:block;width:100%;margin-top:7px;background:none;color:#d7c891;text-align:left;font:500 8px 'DM Mono',monospace;letter-spacing:1px}.manage-link span{float:right;font-size:12px}.nearby-card{padding-bottom:10px}.nearby-item{font-size:9px;color:#bdc8b9;display:flex;align-items:center;gap:7px;margin-top:9px}.nearby-item b{margin-left:auto;color:#e3e3d1;font:500 9px 'DM Mono',monospace}.nearby-dot{height:6px;width:6px;border-radius:50%}.nearby-dot.wild{background:#f1a381}.nearby-dot.harvest{background:#c8d78a}.nearby-dot.water{background:#8ac2d0}.bottom-left{position:absolute;left:35px;bottom:40px;padding:10px 14px;border-radius:8px;display:flex;align-items:center;gap:10px}.compass{width:29px;height:29px;border:1px solid rgba(229,219,179,.4);border-radius:50%;display:grid;place-items:center;color:#e4d092;font:10px 'DM Mono',monospace;position:relative}.compass:after{content:'';position:absolute;left:13px;top:5px;border-left:2px solid transparent;border-right:2px solid transparent;border-bottom:9px solid #e1cc91}.coords strong,.coords span{display:block}.coords strong{font:500 8px 'DM Mono',monospace;color:#e1d29e;letter-spacing:1px}.coords span{font:8px 'DM Mono',monospace;color:#b5c3b4;margin-top:3px}.bottom-center{position:absolute;bottom:24px;left:50%;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:8px}.action-bar{display:flex;padding:7px;gap:6px;border-radius:12px}.action-slot{width:60px;height:60px;background:rgba(229,233,215,.055);border:1px solid rgba(230,235,219,.13);border-radius:8px;position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;transition:background .15s,transform .15s}.action-slot:hover{background:rgba(224,215,177,.15);transform:translateY(-2px)}.action-slot.primary{border-color:rgba(226,192,132,.48);background:rgba(202,167,105,.12)}.slot-key{position:absolute;top:4px;left:6px;font:8px 'DM Mono',monospace;color:#c2cbb8}.action-art{color:#e0cf97;font-size:23px;line-height:24px}.action-slot small{font:500 7px 'DM Mono',monospace;letter-spacing:.8px;color:#d7ddcb}.action-slot em{font-style:normal;color:#e6c981}.cooldown{position:absolute;inset:0;background:rgba(8,17,18,.7);transform:scaleY(0);transform-origin:bottom;pointer-events:none;transition:transform .1s}.control-hint{font:7px 'DM Mono',monospace;color:#c1cbbd;letter-spacing:.7px;text-shadow:0 1px 5px #15211d}.control-hint span{color:#e4d39c}.control-hint i{font-style:normal;margin:0 5px;color:#778a7d}.interact-prompt{position:absolute;left:50%;top:60%;transform:translate(-50%,-50%);display:none;align-items:center;gap:8px;padding:8px 12px;background:rgba(13,25,24,.82);border:1px solid rgba(229,220,181,.24);border-radius:6px;font-size:11px;pointer-events:none}.prompt-key,.tip-key{background:#e2d19a;color:#28352e;border-radius:3px;padding:3px 6px;font:700 9px 'DM Mono',monospace}.world-tip{position:absolute;top:77px;left:50%;transform:translateX(-50%);display:none;align-items:center;gap:7px;color:#e8e9da;font:10px 'DM Mono',monospace;text-shadow:0 1px 4px #111}.toast-stack{position:absolute;top:47%;left:50%;transform:translate(-50%,-50%);display:flex;flex-direction:column;gap:7px;align-items:center;pointer-events:none}.toast{padding:9px 16px;background:rgba(14,28,27,.91);border:1px solid rgba(224,205,149,.4);border-radius:20px;color:#eee8ce;font:10px 'DM Mono',monospace;animation:toastIn .25s ease-out,toastOut .35s 2.4s forwards}@keyframes toastIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}@keyframes toastOut{to{opacity:0;transform:translateY(-7px)}}.combat-banner{position:absolute;left:50%;top:74px;transform:translateX(-50%);font:700 10px 'DM Mono',monospace;color:#ffe0ac;text-shadow:0 1px 6px #40291c;letter-spacing:1px;opacity:0;transition:opacity .2s}.combat-banner.show{opacity:1}.modal-backdrop{position:absolute;inset:0;display:none;align-items:center;justify-content:center;background:rgba(7,15,17,.59);backdrop-filter:blur(5px);z-index:5}.modal-backdrop.open{display:flex}.modal{width:min(520px,calc(100vw - 32px));max-height:85vh;overflow:auto;padding:30px;border-radius:14px;position:relative}.modal-close{position:absolute;right:16px;top:12px;background:none;color:#c9d1c5;font-size:24px}.modal-kicker{color:#d9c68a;font:500 9px 'DM Mono',monospace;letter-spacing:2px}.modal h2{font:700 24px Manrope,sans-serif;margin:8px 0 7px}.modal p{color:#b6c2b7;font-size:12px;line-height:1.65}.modal-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin-top:20px}.modal-card{padding:14px;background:rgba(228,230,212,.06);border:1px solid rgba(228,230,212,.13);border-radius:9px}.modal-card h3{margin:0 0 5px;font:600 12px Manrope,sans-serif}.modal-card p{margin:0;font-size:10px}.modal-creature{display:flex;align-items:center;gap:14px;padding:15px;margin-top:12px;background:rgba(228,230,212,.06);border:1px solid rgba(228,230,212,.13);border-radius:10px}.modal-creature .big-icon{width:54px;height:54px;border-radius:50%;display:grid;place-items:center;background:rgba(178,211,166,.14);font-size:28px}.modal-creature h3{font:700 15px Manrope;margin:0}.modal-creature p{margin:4px 0}.modal-creature button,.modal-cta{margin-left:auto;padding:8px 12px;background:#d9c68b;color:#26342e;border-radius:6px;font:700 9px 'DM Mono',monospace;white-space:nowrap}.modal-cta{display:inline-block;margin:15px 0 0}.inventory-line{display:flex;justify-content:space-between;padding:11px 0;border-bottom:1px solid rgba(255,255,255,.08);font-size:11px;color:#c5cebf}.inventory-line strong{color:#ead899}.modal-note{color:#d7c98f!important;font:9px 'DM Mono',monospace!important;letter-spacing:.4px}.mobile-controls{display:none}.quest-card.collapsed p,.quest-card.collapsed .quest-progress,.quest-card.collapsed .quest-reward{display:none}
@media(max-width:850px){.topbar{height:58px;padding:0 16px}.brand{font-size:11px}.region-pill{font-size:7px;gap:5px;letter-spacing:.8px}.player-card{left:14px;top:72px;width:230px;padding:10px}.quest-card{left:14px;top:170px;width:230px}.right-rail{right:14px;top:72px;width:194px}.nearby-card{display:none}.location-label{top:68px}.location-label strong{font-size:15px}.bottom-left{left:14px;bottom:20px}.bottom-center{bottom:12px}.action-slot{width:53px;height:54px}.control-hint{font-size:6px}.world-vignette{background:linear-gradient(180deg,rgba(8,19,21,.48),transparent 18%,transparent 70%,rgba(9,18,19,.7))}}
@media(max-width:600px){.game-shell{min-height:420px}.topbar{height:50px;padding:0 12px}.brand-mark{font-size:25px}.brand{font-size:10px;gap:7px}.brand small{font-size:7px}.region-pill{left:48%;font-size:6px;max-width:145px;white-space:nowrap;letter-spacing:.5px}.top-actions{gap:5px}.icon-button,.avatar-button{width:29px;height:29px;font-size:14px}.player-card{top:59px;left:9px;width:195px;gap:8px;padding:8px}.portrait{width:35px;height:35px;font-size:19px}.player-name{font-size:11px;margin-bottom:5px}.rank{font-size:6px;margin-left:2px}.stat-label{font-size:6px}.xp-label{margin-top:5px}.quest-card{top:145px;left:9px;width:195px;padding:10px 11px}.quest-heading{font-size:7px;margin-bottom:7px}.quest-card strong{font-size:11px}.quest-card p{font-size:9px;margin:3px 0 8px}.quest-reward{margin-top:7px;padding-top:6px;font-size:7px}.right-rail{right:9px;top:59px;width:155px;gap:7px}.resource-card{padding:8px;gap:7px}.resource-icon{font-size:17px}.resource-card small{font-size:6px}.resource-card strong{font-size:12px}.circle-card{padding:9px}.section-title{font-size:7px;margin-bottom:5px}.creature-row{padding:6px 0;gap:6px}.creature-icon{width:28px;height:28px;font-size:15px}.creature-detail strong{font-size:9px}.creature-detail small,.creature-hp{font-size:7px}.manage-link{font-size:7px;margin-top:4px}.location-label{top:59px}.location-kicker{font-size:6px}.location-label strong{font-size:13px}.location-sub{font-size:8px}.bottom-center{bottom:9px}.action-bar{padding:5px;gap:4px}.action-slot{width:48px;height:48px}.action-art{font-size:19px;line-height:19px}.action-slot small{font-size:6px}.slot-key{font-size:7px}.control-hint{display:none}.bottom-left{display:none}.mobile-controls{display:block;position:absolute;inset:auto 0 0;pointer-events:none}.dpad{position:absolute;left:12px;bottom:78px;display:flex;flex-direction:column;align-items:center;gap:3px;pointer-events:auto}.dpad div{display:flex;gap:3px}.dpad button,.mobile-actions button{width:35px;height:33px;border-radius:7px;background:rgba(15,29,30,.6);border:1px solid rgba(234,236,218,.24);color:#e2dfc8;font-size:12px;touch-action:none}.mobile-actions{position:absolute;right:12px;bottom:82px;display:flex;gap:6px;pointer-events:auto}.mobile-actions button{width:42px;height:42px;border-radius:50%;font-size:15px;background:rgba(18,37,35,.75)}.interact-prompt{top:58%}.toast-stack{top:42%}.modal{padding:24px 20px}.modal h2{font-size:20px}.modal-grid{gap:7px}.modal-card{padding:10px}.world-tip{top:52px;font-size:8px}}
@media(max-height:640px) and (min-width:601px){.player-card{top:78px}.quest-card{top:190px}.right-rail{top:78px}.location-label{top:85px}.bottom-center{bottom:12px}.bottom-left{bottom:20px}}

(() => {
  'use strict';
  const canvas = document.getElementById('world'), ctx = canvas.getContext('2d');
  const ui = id => document.getElementById(id);
  const TAU = Math.PI * 2;
  let W = 0, H = 0, dpr = 1, last = 0, tick = 0, cam = {x: 1100, y: 680};
  const keys = new Set(), held = new Set();
  const player = {x:1100,y:680,hp:100,maxHp:100,xp:0,level:1,coins:12,orbs:3,speed:160,dir:0,moving:false,dodge:0,attack:0,invuln:0};
  const species = {
    Mossling:{element:'Verdant',icon:'❋',color:'#a9c77f',dark:'#587c55',accent:'#ead38c',skill:'Rootsnare',mount:'gallop'},
    Cindercub:{element:'Ember',icon:'✹',color:'#ed9a6d',dark:'#995842',accent:'#ffcf8e',skill:'Flare',mount:'sprint'},
    Galelet:{element:'Aerial',icon:'✧',color:'#b8d5c9',dark:'#718f91',accent:'#f2dfa4',skill:'Updraft',mount:'flight'},
    Tidekip:{element:'Tidal',icon:'❧',color:'#79b8c2',dark:'#426f87',accent:'#c9ecdc',skill:'Undertow',mount:'swim'},
    Duskrabbit:{element:'Lunar',icon:'☾',color:'#c6a9c8',dark:'#705878',accent:'#f5d894',skill:'Moonbeam',mount:'blink'}
  };
  let team = [{name:'Mossling',level:1,hp:42,maxHp:42,xp:0}];
  let active=0, mounted=false, relicEquipped=false, summoned=true, gathering=0, creatureQuest=0, kills=0, collapsedQuest=false, modalOpen=false, attackCooldown=0, skillCooldown=0, combatUntil=0, day=1, mapOverlay=false;
  let inventory={Moonbloom:0,Sunberry:0,Shard:0,Armor:0};
  const terrain=[];
  const rand=(a,b)=>a+Math.random()*(b-a), clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  const seeded = n => {let x=Math.sin(n*127.1+311.7)*43758.5453; return x-Math.floor(x)};
  const areas=[{x:0,y:0,w:890,h:1900,type:'forest'},{x:890,y:0,w:1150,h:1900,type:'meadow'},{x:2040,y:0,w:900,h:1900,type:'coast'}];
  const entities=[];
  function makeEntity(kind,x,y,extra={}){const e={kind,x,y,r:kind==='enemy'?21:13,alive:true,phase:rand(0,TAU),...extra};entities.push(e);return e;}
  // Gatherables and roaming creatures are placed once, then persist in the world.
  const gatherKinds=['Moonbloom','Sunberry','Moonbloom','Shard'];
  for(let i=0;i<34;i++){const x=260+seeded(i+4)*2500,y=180+seeded(i+87)*1500;makeEntity(gatherKinds[i%4],x,y,{r:12,respawn:0});}
  const wildSpecies=['Cindercub','Galelet','Tidekip','Duskrabbit','Mossling'];
  for(let i=0;i<12;i++){const x=400+seeded(i+190)*2200,y=250+seeded(i+340)*1400;makeEntity('enemy',x,y,{species:wildSpecies[i%wildSpecies.length],hp:38+Math.floor(seeded(i+4)*18),maxHp:38+Math.floor(seeded(i+4)*18),speed:30+seeded(i+1)*15,aggro:false});}
  makeEntity('npc',1260,510,{name:'Elder Rowan'});
  const close=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
  function resize(){dpr=Math.min(window.devicePixelRatio||1,2);W=canvas.clientWidth;H=canvas.clientHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);}
  window.addEventListener('resize',resize);resize();

  function areaAt(x){return x<890?'Whisperwood':x<2040?'Mosslight Meadow':'Glasswater Shore';}
  function paintGround(){
    const left=cam.x-W/2-80, top=cam.y-H/2-80;
    ctx.fillStyle='#547a53';ctx.fillRect(left,top,W+160,H+160);
    // broad painterly color patches
    for(let i=0;i<90;i++){let x=Math.floor(left/320+i%10)*320+seeded(i+40)*320,y=Math.floor(top/300+Math.floor(i/10))*300+seeded(i+120)*300;ctx.fillStyle=i%4===0?'rgba(181,183,117,.12)':i%3===0?'rgba(32,82,61,.15)':'rgba(213,195,123,.045)';ctx.beginPath();ctx.ellipse(x,y,100+seeded(i)*180,50+seeded(i+33)*120,seeded(i+7),0,TAU);ctx.fill();}
    // winding, pale trail crossing the meadow
    ctx.save();ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-100,cam.y+350);ctx.bezierCurveTo(cam.x-500,cam.y+300,cam.x-280,cam.y+50,cam.x+20,cam.y+100);ctx.bezierCurveTo(cam.x+320,cam.y+150,cam.x+220,cam.y-170,cam.x+600,cam.y-260);ctx.strokeStyle='rgba(201,184,127,.23)';ctx.lineWidth=118;ctx.stroke();ctx.strokeStyle='rgba(216,202,157,.16)';ctx.lineWidth=92;ctx.stroke();ctx.restore();
    // shore and water pool. The water shifts with a subtle light shimmer.
    ctx.fillStyle='#263f37';ctx.beginPath();ctx.ellipse(2260,780,370,590,-.17,0,TAU);ctx.fill();ctx.fillStyle='#457f85';ctx.beginPath();ctx.ellipse(2300,765,320,545,-.17,0,TAU);ctx.fill();ctx.fillStyle='#548f91';ctx.beginPath();ctx.ellipse(2294,755,286,500,-.17,0,TAU);ctx.fill();
    for(let i=0;i<26;i++){let x=2110+seeded(i+500)*400,y=320+seeded(i+540)*900;ctx.strokeStyle=`rgba(202,230,206,${.06+.04*Math.sin(tick/900+i)})`;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(x,y,15+seeded(i)*30,3+seeded(i+2)*7,-.2,0,TAU);ctx.stroke();}
    // stream at the west side
    ctx.fillStyle='#345c58';ctx.beginPath();ctx.moveTo(820,-200);ctx.bezierCurveTo(1040,100,730,230,900,500);ctx.bezierCurveTo(1060,760,710,850,870,1200);ctx.bezierCurveTo(1020,1500,730,1650,880,2000);ctx.lineTo(980,2000);ctx.bezierCurveTo(830,1640,1120,1500,970,1200);ctx.bezierCurveTo(820,850,1160,750,1000,500);ctx.bezierCurveTo(840,230,1140,100,910,-200);ctx.closePath();ctx.fill();
