function updatePrompt(){const e=closest(x=>['Moonbloom','Sunberry','Shard','npc'].includes(x.kind),112);const wild=closest(x=>x.kind==='enemy'&&x.hp<x.maxHp*.72,115);let target=e||wild;const p=ui('interact-prompt');if(target){p.style.display='flex';ui('prompt-text').textContent=target.kind==='npc'?'Speak with Rowan':target.kind==='enemy'?`Invite ${target.species}`:`Gather ${target.kind}`;}else p.style.display='none';}
function toast(message){const t=document.createElement('div');t.className='toast';t.textContent=message;ui('toasts').appendChild(t);setTimeout(()=>t.remove(),2900);}
function addXP(amount){player.xp+=amount;while(player.xp>=80+(player.level-1)*35){player.xp-=80+(player.level-1)*35;player.level++;player.maxHp+=12;player.hp=player.maxHp;player.coins+=4;team.forEach(c=>{c.level++;c.maxHp+=5;c.hp=c.maxHp;});toast(`Wayfarer level ${player.level} · your circle grew stronger`);}}
function openModal(kicker,title,body){modalOpen=true;ui('modal-content').innerHTML=`<div class="modal-kicker">${kicker}</div><h2>${title}</h2>${body}`;ui('modal-backdrop').classList.add('open');}
function closeModal(){modalOpen=false;ui('modal-backdrop').classList.remove('open');}
function interact(){const gather=closest(x=>['Moonbloom','Sunberry','Shard'].includes(x.kind),112);if(gather){gather.alive=false;inventory[gather.kind]++;if(gather.kind==='Shard')player.coins+=2;else player.coins++;gathering++;addXP(5);toast(gather.kind==='Shard'?'Moonstone shard found · +2 moonstones':`${gather.kind} gathered · +1 moonstone`);if(gathering>=3&&!collapsedQuest)questProgress(0);return;}const npc=closest(x=>x.kind==='npc',112);if(npc){openModal('A WAYFARER’S TALE','The old trail remembers',`<p>“The Shardwilds are waking again,” Rowan says, watching the little Mossling at your side. “Be kind to the wild ones. A good companion is worth more than a full satchel.”</p><p>Gather moonbloom for salves, and watch the shore when the moon is high. You may find a creature there that knows how to ride the wind.</p><div class="modal-note">TRAIL TIP · WOUNDED WILD CREATURES CAN BE INVITED WITH E</div><button class="modal-cta" onclick="document.getElementById('modal-close').click()">I’LL REMEMBER</button>`);return;}const wild=closest(x=>x.kind==='enemy'&&x.hp<x.maxHp*.72,115);if(wild)capture(wild);else toast('Nothing nearby to interact with.');}
function capture(e){if(team.length>=4){toast('Your circle is full. Visit the companion menu to make room.');return;}if(player.orbs<=0){toast('You need a moon-orb to invite a companion.');return;}player.orbs--;let chance=e.hp<e.maxHp*.35?.96:.74;if(Math.random()>chance){toast(`${e.species} slipped away — try weakening it first.`);e.aggro=false;return;}e.alive=false;team.push({name:e.species,level:Math.max(1,player.level),hp:42+player.level*4,maxHp:42+player.level*4,xp:0});creatureQuest++;addXP(12);player.coins+=2;toast(`${e.species} joined your circle! · +2 moonstones`);if(creatureQuest===1)questProgress(1);updateUI();}
function questProgress(caught){if(caught){ui('quest-title').textContent='A Circle of Your Own';ui('quest-copy').textContent='A new friend! Keep exploring and strengthen your circle.';ui('quest-count').textContent='COMPLETE';ui('quest-bar').style.width='100%';ui('quest-reward').innerHTML='✦ <span>TRAIL COMPLETE</span><span>·</span><span>35 XP CLAIMED</span>';addXP(35);player.coins+=2;player.orbs++;toast('Trail complete · 35 XP · 2 moonstones · +1 moon-orb');}else{ui('quest-copy').textContent='A little gathering goes a long way. Find a wild creature next.';ui('quest-count').textContent='3 / 3';ui('quest-bar').style.width='100%';}}
function attack(){if(attackCooldown>0)return;attackCooldown=.58;player.attack=.24;const target=closest(e=>e.kind==='enemy',175);if(!target){toast('Your companion’s light shimmers around you.');return;}target.hp-=team[active].level*16+20;target.aggro=true;combatUntil=performance.now()+1200;ui('combat-banner').textContent=`${species[team[active].name].skill.toUpperCase()} · ${target.species}  −${team[active].level*16+20}`;ui('combat-banner').classList.add('show');setTimeout(()=>ui('combat-banner').classList.remove('show'),900);if(target.hp<=0){target.alive=false;kills++;addXP(26);player.coins+=3;inventory.Shard++;team[active].xp+=20;toast(`${target.species} calmed · +26 XP · loot found`);}else if(target.hp<target.maxHp*.72)toast(`${target.species} is wavering · press E to invite`);}
function toggleMount(){if(!team.length){toast('Find a companion to ride.');return;}mounted=!mounted;if(mounted){summoned=false;const mount=species[team[active].name].mount;toast(mount==='flight'?`${team[active].name} takes to the air`:mount==='swim'?`${team[active].name} glides across the water`:`Riding ${team[active].name}`);}else toast('Back on foot.');updateUI();}
function toggleSummon(){if(!team.length){toast('Invite a creature before summoning.');return;}if(mounted)mounted=false;summoned=!summoned;toast(summoned?`${team[active].name} joins your side`:'Your companion returns to its circle');}
function useRelic(){if(!relicEquipped){openModal('RELIC WARDROBE','A little borrowed magic',`<p>Your relic carries an old enchantment. Choose one to keep close on the trail.</p><div class="modal-grid"><article class="modal-card"><h3>🌙 Wayfinder Charm</h3><p>Recover a little vitality after each gathering. Yours to keep.</p><button class="modal-cta" onclick="gameEquipRelic('Wayfinder Charm')">EQUIP · FREE</button></article><article class="modal-card"><h3>🪶 Skydrift Feather</h3><p>Move 12% faster on foot. A gift from the wind.</p><button class="modal-cta" onclick="gameEquipRelic('Skydrift Feather')">EQUIP · 8 ◈</button></article></div>`);return;}relicEquipped=false;player.speed=160;toast('Relic unequipped.');}
window.gameEquipRelic=(name)=>{if(name==='Skydrift Feather'){if(player.coins<8){toast('You need 8 moonstones for that relic.');return;}player.coins-=8;player.speed=179;}else{relicEquipped=true;}relicEquipped=true;closeModal();toast(`${name} equipped`);};
function openCreatureMenu(){let rows=team.map((c,i)=>`<div class="modal-creature"><div class="big-icon">${species[c.name].icon}</div><div><h3>${c.name} <span style="color:#d8c68b;font-size:10px">LV ${c.level}</span></h3><p>${species[c.name].element} · ${species[c.name].skill} · ${c.hp}/${c.maxHp} vitality</p><div class="modal-note">${c.xp||0} TRAINING XP</div></div><button onclick="gameSetActive(${i})">${i===active?'ACTIVE':'SELECT'}</button></div>`).join('');let wild=entities.filter(e=>e.alive&&e.kind==='enemy').slice(0,0);openModal('YOUR COMPANIONS','A growing circle',`<p>Companions gain training from every battle. Choose who follows, rides, and shares their gift with you.</p>${rows}<div class="modal-grid"><article class="modal-card"><h3>✧ Summoning</h3><p>Summon your active companion as a field ally, or ride them for faster travel.</p></article><article class="modal-card"><h3>⌁ Training</h3><p>Each victory gives your active companion training XP. Wayfarer levels strengthen the whole circle.</p></article></div>`);}
window.gameSetActive=(i)=>{if(!team[i])return;active=i;mounted=false;summoned=true;closeModal();toast(`${team[active].name} is now your active companion`);updateUI();};
function openInventory(){let rows=Object.entries(inventory).map(([k,v])=>`<div class="inventory-line"><span>${k==='Moonbloom'?'✿':k==='Sunberry'?'●':'◈'} &nbsp;${k}</span><strong>${v}</strong></div>`).join('');openModal('TRAVELER’S SATCHEL','Collected along the way',`<p>Little things gathered on a long trail.</p>${rows}<div class="modal-grid"><article class="modal-card"><h3>🧥 Wayfarer Mantle</h3><p>Sturdy trail armor. ${inventory.Armor?'Owned — equipped':'Keepsake armor · 10 moonstones'}</p><button class="modal-cta" onclick="gameBuyArmor()">${inventory.Armor?'EQUIPPED':'CRAFT · 10 ◈'}</button></article><article class="modal-card"><h3>◌ Moon-orbs</h3><p>${player.orbs} left · Invite weakened wild creatures.</p><button class="modal-cta" onclick="gameBuyOrb()">BUY · 3 ◈</button></article></div>`);}
window.gameBuyArmor=()=>{if(inventory.Armor){toast('Your mantle is ready for the trail.');return;}if(player.coins<10){toast('You need 10 moonstones to craft the mantle.');return;}player.coins-=10;inventory.Armor=1;player.maxHp+=20;player.hp=player.maxHp;closeModal();toast('Wayfarer Mantle crafted · +20 vitality');};
window.gameBuyOrb=()=>{if(player.coins<3){toast('You need 3 moonstones for a moon-orb.');return;}player.coins-=3;player.orbs++;closeModal();toast('Moon-orb added to your satchel.');};
function openJournal(){openModal('FIELD JOURNAL','Notes from Mosslight',`<p>In the Shardwilds, every creature has an element, a field gift, and its own way of moving through the world.</p><div class="modal-grid"><article class="modal-card"><h3>✹ Ember · Cindercub</h3><p>Fast on the ground. Flare leaves a warm, bright mark.</p></article><article class="modal-card"><h3>✧ Aerial · Galelet</h3><p>Soars over streams and shoreline. The wind opens hidden paths.</p></article><article class="modal-card"><h3>❧ Tidal · Tidekip</h3><p>Swims with ease. A friend to have near Glasswater Shore.</p></article><article class="modal-card"><h3>❋ Verdant · Mossling</h3><p>A steady companion, and a gentle guide to the old woods.</p></article></div><p class="modal-note">WASD MOVE · SHIFT RUN · SPACE DODGE · Q COMPANION GIFT · E INTERACT</p>`);}

