  function openJournal(){openModal('FIELD JOURNAL','Notes from Mosslight',`<p>In the Shardwilds, every creature has an element, a field gift, and its own way of moving through the world.</p><div class="modal-grid"><article class="modal-card"><h3>✹ Ember · Cindercub</h3><p>Fast on the ground. Flare leaves a warm, bright mark.</p></article><article class="modal-card"><h3>✧ Aerial · Galelet</h3><p>Soars over streams and shoreline. The wind opens hidden paths.</p></article><article class="modal-card"><h3>❧ Tidal · Tidekip</h3><p>Swims with ease. A friend to have near Glasswater Shore.</p></article><article class="modal-card"><h3>❋ Verdant · Mossling</h3><p>A steady companion, and a gentle guide to the old woods.</p></article></div><p class="modal-note">WASD MOVE · SHIFT RUN · SPACE DODGE · Q COMPANION GIFT · E INTERACT</p>`);}
  function openMap(){openModal('THE SHARDWILDS','Your trail so far',`<p>Everywhere is just one path away. Your marker is the gold star.</p><div class="map-panel"><svg viewBox="0 0 460 260" role="img" aria-label="Map of the Shardwilds"><defs><linearGradient id="grassMap" x2="1" y2="1"><stop stop-color="#304d3c"/><stop offset="1" stop-color="#75865d"/></linearGradient></defs><rect width="460" height="260" rx="8" fill="url(#grassMap)"/><path d="M0 64 Q105 92 147 24 T270 58" fill="none" stroke="#263c33" stroke-width="50"/><path d="M260 0 Q205 81 265 133 T219 260" fill="none" stroke="#568d87" stroke-width="32"/><ellipse cx="370" cy="148" rx="55" ry="100" fill="#477d83"/><path d="M65 225 Q147 188 208 145 T352 81" fill="none" stroke="#c7b989" stroke-width="14"/><path d="M66 225 Q147 188 208 145 T352 81" fill="none" stroke="#e0d1a3" stroke-width="2" stroke-dasharray="3 7"/><g fill="#a9b986" opacity=".8"><circle cx="44" cy="79" r="3"/><circle cx="81" cy="42" r="4"/><circle cx="113" cy="121" r="3"/><circle cx="179" cy="49" r="3"/><circle cx="158" cy="218" r="4"/><circle cx="316" cy="220" r="3"/></g><text x="45" y="30" fill="#dae0c3" font-size="10" font-family="monospace">WHISPERWOOD</text><text x="151" y="122" fill="#f1e7c4" font-size="10" font-family="monospace">MOSSLIGHT MEADOW</text><text x="325" y="30" fill="#dae0c3" font-size="10" font-family="monospace">GLASSWATER</text><text x="${clamp(player.x/2860*400+25,20,430)}" y="${clamp(player.y/1900*220+15,20,245)}" fill="#f5d58b" font-size="20">✦</text></svg><div class="map-legend"><span>✦ YOU ARE HERE</span><span>◉ WILD CREATURES</span><span>◈ GATHERABLES</span></div></div><div class="modal-note">WHISPERWOOD · MOSSLIGHT MEADOW · GLASSWATER SHORE</div>`);}
  function saveGame(){try{localStorage.setItem('wildbound-save',JSON.stringify({player:{level:player.level,xp:player.xp,hp:player.hp,coins:player.coins,orbs:player.orbs,x:player.x,y:player.y,maxHp:player.maxHp},team,active,inventory,relicEquipped}));}catch(_){}}
  function loadGame(){try{const s=JSON.parse(localStorage.getItem('wildbound-save'));if(!s)return;Object.assign(player,s.player||{});if(Array.isArray(s.team)&&s.team.length)team=s.team;active=clamp(s.active||0,0,team.length-1);if(s.inventory)inventory=s.inventory;relicEquipped=!!s.relicEquipped;if(relicEquipped)player.speed=179;}catch(_){}}
  function frame(now){const dt=Math.min(.04,(now-last)/1000||0);last=now;tick=now;move(dt);updateEnemies(dt);render();updateUI();requestAnimationFrame(frame);}
  loadGame();cam.x=player.x;cam.y=player.y;
  window.addEventListener('keydown',e=>{let key=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(key))e.preventDefault();if(modalOpen){if(key==='escape')closeModal();return;}if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright','shift'].includes(key))keys.add(key);if(held.has(key))return;held.add(key);if(key==='e')interact();if(key==='q')attack();if(key==='1')toggleSummon();if(key==='2')toggleMount();if(key==='3'){const wild=closest(x=>x.kind==='enemy'&&x.hp<x.maxHp*.72,115);if(wild)capture(wild);else toast('Weaken a wild creature before inviting it.');}if(key==='4')useRelic();if(key===' ')player.dodge=.24;});
  window.addEventListener('keyup',e=>{let key=e.key.toLowerCase();keys.delete(key);held.delete(key);});window.addEventListener('blur',()=>{keys.clear();held.clear();});
  ui('attack-btn').addEventListener('click',attack);ui('summon-btn').addEventListener('click',toggleSummon);ui('mount-btn').addEventListener('click',toggleMount);ui('capture-btn').addEventListener('click',()=>{const wild=closest(x=>x.kind==='enemy'&&x.hp<x.maxHp*.72,115);if(wild)capture(wild);else toast('Weaken a wild creature before inviting it.');});ui('relic-btn').addEventListener('click',useRelic);ui('bag-btn').addEventListener('click',openInventory);ui('creatures-btn').addEventListener('click',openCreatureMenu);ui('journal-btn').addEventListener('click',openJournal);ui('map-btn').addEventListener('click',openMap);ui('profile-btn').addEventListener('click',()=>openModal('TRAIL PROFILE','Aster, Wayfarer',`<p>A level ${player.level} explorer with ${team.length} companions and a lot of trail left to find.</p><div class="modal-grid"><article class="modal-card"><h3>✦ Wayfarer level</h3><p>${player.level} · experience ${player.xp}</p></article><article class="modal-card"><h3>❋ Wild friends</h3><p>${team.length} companions · ${kills} wild encounters calmed</p></article></div><div class="modal-note">PROGRESS SAVES AUTOMATICALLY ON THIS DEVICE</div>`));ui('rest-btn').addEventListener('click',()=>{player.hp=player.maxHp;team.forEach(c=>c.hp=c.maxHp);toast('A quiet moment by the trail · vitality restored');});ui('quest-toggle').addEventListener('click',()=>{collapsedQuest=!collapsedQuest;ui('quest-card')?.classList.toggle('collapsed',collapsedQuest);document.querySelector('.quest-card').classList.toggle('collapsed',collapsedQuest);ui('quest-toggle').textContent=collapsedQuest?'⌄':'⌃';});ui('modal-close').addEventListener('click',closeModal);ui('modal-backdrop').addEventListener('click',e=>{if(e.target===ui('modal-backdrop'))closeModal();});ui('touch-interact').addEventListener('click',interact);ui('touch-attack').addEventListener('click',attack);document.querySelectorAll('.dpad button').forEach(b=>{const dir=b.dataset.dir, map={up:'w',down:'s',left:'a',right:'d'};b.addEventListener('pointerdown',e=>{e.preventDefault();keys.add(map[dir]);b.setPointerCapture(e.pointerId);});const release=()=>keys.delete(map[dir]);b.addEventListener('pointerup',release);b.addEventListener('pointercancel',release);b.addEventListener('lostpointercapture',release);});ui('team-list').addEventListener('click',e=>{const row=e.target.closest('[data-team]');if(row)window.gameSetActive(Number(row.dataset.team));});
  document.querySelectorAll('.action-slot').forEach((el,i)=>el.title=['Companion gift · Q','Summon companion · 1','Mount companion · 2','Invite a weakened creature · 3','Equip a relic · 4'][i]);
  setInterval(()=>{let now=new Date(),hours=8+Math.floor(now.getMinutes()/60),mins=now.getMinutes();ui('clock').textContent=`DAY ${String(day).padStart(2,'0')} · ${String(hours).padStart(2,'0')}:${String(mins).padStart(2,'0')}`;},10000);setInterval(saveGame,5000);window.addEventListener('beforeunload',saveGame);updateUI();requestAnimationFrame(frame);
})();

